package org.marketreview.nativeapp;
import android.content.Context;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.*;
import org.json.*;
final class PersonMethodStore extends SQLiteOpenHelper {
 PersonMethodStore(Context c,String name){super(c,name,null,1);}
 public void onCreate(SQLiteDatabase db){PersonMethodModel.need(scalar(db,"SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='android_metadata'")==0,"不是空独立人物方法库，未重建");db.execSQL("CREATE TABLE pm_records(kind TEXT NOT NULL,id TEXT NOT NULL,entity_id TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(kind,id))");db.execSQL("PRAGMA application_id=1347235889");}
 public void onOpen(SQLiteDatabase db){super.onOpen(db);PersonMethodModel.need(scalar(db,"PRAGMA application_id")==1347235889&&scalar(db,"PRAGMA user_version")==1,"库身份/版本不支持，未重建");try(Cursor c=db.rawQuery("SELECT kind,id,entity_id,payload FROM pm_records LIMIT 0",null)){c.moveToFirst();}}
 public void onUpgrade(SQLiteDatabase db,int old,int next){throw new IllegalStateException("人物方法库需明确迁移，未清空");}
 private static int scalar(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){PersonMethodModel.need(c.moveToFirst(),"库身份读取失败");return c.getInt(0);}}
 private static JSONObject payload(SQLiteDatabase db,String kind,String id)throws Exception{try(Cursor header=db.rawQuery("SELECT length(payload) FROM pm_records WHERE kind=? AND id=?",new String[]{kind,id})){if(!header.moveToFirst())return new JSONObject();long length=header.getLong(0);PersonMethodModel.need(length>0&&length<=25*1024*1024,"版本原记录过大或损坏，未截断");StringBuilder text=new StringBuilder();for(long start=1;start<=length;start+=24000)try(Cursor c=db.rawQuery("SELECT substr(payload,?,24000) FROM pm_records WHERE kind=? AND id=?",new String[]{Long.toString(start),kind,id})){PersonMethodModel.need(c.moveToFirst()&&!c.isNull(0)&&!c.getString(0).isEmpty(),"分块读取不完整");text.append(c.getString(0));}PersonMethodModel.need(text.codePointCount(0,text.length())==length,"完整原文长度不一致");return PersonMethodModel.validate(new JSONObject(text.toString()));}}
 private JSONArray rows(String kind)throws Exception{SQLiteDatabase db=getReadableDatabase();JSONArray out=new JSONArray();try(Cursor c=db.rawQuery("SELECT id FROM pm_records WHERE kind=? ORDER BY rowid",new String[]{kind})){while(c.moveToNext())out.put(payload(db,kind,c.getString(0)));}return out;}
 JSONObject backup()throws Exception{SQLiteDatabase db=getReadableDatabase();boolean own=!db.inTransaction();if(own)db.beginTransactionNonExclusive();try{JSONObject out=PersonMethodModel.empty();for(String k:new String[]{"subjects","sources","methods"})out.put(k,rows(k));if(own)db.setTransactionSuccessful();return out;}finally{if(own)db.endTransaction();}}
 JSONObject get(String kind,String id)throws Exception{SQLiteDatabase db=getReadableDatabase();boolean own=!db.inTransaction();if(own)db.beginTransactionNonExclusive();try{JSONObject r=payload(db,kind,id);if(own)db.setTransactionSuccessful();return r;}finally{if(own)db.endTransaction();}}
 JSONObject latest(String kind,String entity)throws Exception{SQLiteDatabase db=getReadableDatabase();boolean own=!db.inTransaction();if(own)db.beginTransactionNonExclusive();try{JSONObject out=new JSONObject();try(Cursor c=db.rawQuery("SELECT id FROM pm_records WHERE kind=? AND entity_id=? ORDER BY rowid DESC LIMIT 1",new String[]{kind,entity})){if(c.moveToFirst())out=payload(db,kind,c.getString(0));}if(own)db.setTransactionSuccessful();return out;}finally{if(own)db.endTransaction();}}
 private static void insert(SQLiteDatabase db,JSONObject r)throws Exception{PersonMethodModel.validate(r);ContentValues v=new ContentValues();v.put("kind",r.getString("kind"));v.put("id",r.getString("id"));v.put("entity_id",r.getString("entityId"));v.put("payload",r.toString());db.insertOrThrow("pm_records",null,v);}
 JSONObject append(JSONObject input,JSONObject expected)throws Exception{JSONObject r=PersonMethodModel.seal(input);SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject current=latest(r.getString("kind"),r.getString("entityId"));PersonMethodModel.need(PersonMethodModel.canonical(current).equals(PersonMethodModel.canonical(expected)),"对象或方法最新版本已变化，草稿未覆盖，请显式重读或放弃");PersonMethodModel.need(r.getString("parentId").equals(current.optString("id")),"父版本不匹配");insert(db,r);db.setTransactionSuccessful();return r;}finally{db.endTransaction();}}
 void merge(JSONObject incoming,JSONObject expected)throws Exception{JSONObject input=PersonMethodModel.decode(incoming.toString());SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{JSONObject current=backup();PersonMethodModel.need(PersonMethodModel.canonical(current).equals(PersonMethodModel.canonical(expected)),"人物方法库已变化，请重新预览，未写入");JSONObject inserts=PersonMethodModel.preview(input,current).getJSONObject("inserts");for(String k:new String[]{"subjects","sources","methods"}){JSONArray rows=inserts.getJSONArray(k);for(int i=0;i<rows.length();i++)insert(db,rows.getJSONObject(i));}db.setTransactionSuccessful();}finally{db.endTransaction();}}
}
